assert_inspected_log_path() {
    local state_file=${1:?state JSON required} log_path unresolved
    unresolved=$(node -p "JSON.parse(require('fs').readFileSync(process.argv[1])).unresolved" "$state_file") || return 4
    [[ "$unresolved" == true ]] || return 0
    log_path=$(node -p "JSON.parse(require('fs').readFileSync(process.argv[1])).log_path" "$state_file") || return 4
    harness_assert_repo_path .ai-harness dir &&
        harness_assert_repo_path .ai-harness/logs dir &&
        harness_assert_repo_path "$log_path" file
}

mark_log_path_unsafe() {
    local state_file=${1:?state JSON required}
    node - "$state_file" <<'NODE'
const fs=require('fs'),file=process.argv[2],x=JSON.parse(fs.readFileSync(file));x.eligible=false;x.issues=Array.isArray(x.issues)?x.issues:[];if(!x.issues.includes('archive log path has a symlink, unsafe ancestor, or non-file target'))x.issues.push('archive log path has a symlink, unsafe ancestor, or non-file target');fs.writeFileSync(file,JSON.stringify(x,null,2)+'\n');
NODE
}

